export const ui = new UI();

// ui-menus.js — pause menu, inventory, shop
import { Input, clamp } from './util.js';
import { audio } from './audio.js';
import { ui } from './ui.js';
import { ITEMS, SKILLS, STATUS_INFO } from './data.js';

const bar = (cls, pct) => `<div class="bar ${cls}"><i style="width:${clamp(pct, 0, 1) * 100}%"></i></div>`;

function statusHTML(game) {
  return `<div class="stat-grid">${game.party.map((m) => {
    const allSkills = (game.chars?.[m.id]?.skills) || [];
    return `<div class="stat-card">
      <div class="sc-head">
        <div><div class="sc-name">${m.name}</div><div class="sc-role">${m.role}</div></div>
        <div class="sc-lvl">Nv ${m.level}</div>
      </div>
      <div class="stat-bars">
        <div class="stat-line"><span>HP</span>${bar('hp', m.hp / m.maxHp)}<b>${m.hp}/${m.maxHp}</b></div>
        <div class="stat-line"><span>MP</span>${bar('mp', m.mp / m.maxMp)}<b>${m.mp}/${m.maxMp}</b></div>
      </div>
      <div class="stat-attrs">
        <div class="stat-attr">ATQ<b>${m.atk}</b></div>
        <div class="stat-attr">DEF<b>${m.def}</b></div>
        <div class="stat-attr">MAG<b>${m.mag}</b></div>
        <div class="stat-attr">RES<b>${m.res}</b></div>
        <div class="stat-attr">VEL<b>${m.spd}</b></div>
        <div class="stat-attr">SOR<b>${m.lck}</b></div>
      </div>
      <div class="sc-skills">${m.skills.map((sid) => `<span class="skill-tag">${SKILLS[sid]?.name || sid}</span>`).join('')}</div>
    </div>`;
  }).join('')}</div>`;
}

function itemsHTML(game) {
  const consumables = Object.keys(game.inventory).filter((id) => ITEMS[id] && !ITEMS[id].key && game.inventory[id] > 0);
  const keys = Object.keys(game.inventory).filter((id) => ITEMS[id]?.key && game.inventory[id] > 0);
  if (!consumables.length && !keys.length) return '<div class="key-note">A mochila está vazia. O vento também estava.</div>';
  let html = '<div class="item-list">';
  for (const id of consumables) {
    const it = ITEMS[id];
    html += `<div class="item-row clickable" data-item="${id}">
      <div class="item-ico">${it.icon || '◈'}</div>
      <div class="item-name">${it.name}<small>${it.desc}</small></div>
      <div class="item-qty">x${game.inventory[id]}</div>
      <div class="item-use">Usar</div>
    </div>`;
  }
  if (keys.length) {
    html += `<div style="margin:14px 0 6px;font-family:var(--pixel);font-size:7px;color:var(--gold);letter-spacing:1px">ITENS DE HISTÓRIA</div>`;
    for (const id of keys) {
      const it = ITEMS[id];
      html += `<div class="item-row">
        <div class="item-ico">${it.icon || '✦'}</div>
        <div class="item-name">${it.name}<small>${it.desc}</small></div>
        <div class="item-qty">—</div>
      </div>`;
    }
  }
  html += '</div>';
  return html;
}

function journalHTML(game) {
  const list = game.journal || [];
  if (!list.length) return '<div class="key-note">Nenhum objetivo registrado ainda.</div>';
  return `<div class="journal-list">${list.map((j) => `
    <div class="journal-item ${j.active ? 'active' : ''}">
      <span class="j-ch">${j.chapter || ''}${j.active ? ' · EM ANDAMENTO' : ' · CONCLUÍDO'}</span>
      ${j.text}
    </div>`).join('')}</div>`;
}

export async function pauseMenu(game, actions = {}) {
  const content = document.createElement('div');
  content.className = 'screen pause-screen';
  content.innerHTML = `
    <div class="screen-head">
      <div class="screen-title">Diário de Jornada</div>
      <div style="display:flex;align-items:center;gap:12px">
        <span style="font-size:16px;color:var(--muted)">${game.playTimeLabel || ''}</span>
        <button class="screen-close">Fechar</button>
      </div>
    </div>
    <div class="pause-layout">
      <nav class="pause-nav">
        <button class="pnav-btn" data-tab="status"><span class="ico">◈</span>Status</button>
        <button class="pnav-btn" data-tab="items"><span class="ico">✦</span>Itens</button>
        <button class="pnav-btn" data-tab="journal"><span class="ico">✧</span>Diário</button>
        <button class="pnav-btn" data-tab="save"><span class="ico">⚿</span>Salvar</button>
        <button class="pnav-btn" data-tab="system"><span class="ico">⚙</span>Sistema</button>
      </nav>
      <div class="pause-content" id="pause-content"></div>
    </div>
    <div style="padding:8px 16px 12px;font-size:14px;color:var(--muted);border-top:1px solid rgba(231,199,123,.12)">
      ↑↓ navegar · ←→ trocar aba · Enter selecionar · Esc voltar
    </div>`;
  ui.openScreen(content, { dim: true });
  audio.sfx('confirm');

  const tabs = ['status', 'items', 'journal', 'save', 'system'];
  let tabIndex = 0;
  let navIndex = 0;
  let contentIndex = 0;
  let focus = 'nav';
  const navBtns = [...content.querySelectorAll('.pnav-btn')];
  const contentEl = content.querySelector('#pause-content');
  let contentActions = [];

  const renderNav = () => {
    navBtns.forEach((b, i) => {
      b.classList.toggle('sel', i === navIndex && focus === 'nav');
      b.style.outline = (i === navIndex && focus === 'content') ? '1px solid rgba(231,199,123,.28)' : '';
    });
  };

  const useItem = async (id) => {
    const it = ITEMS[id];
    if (!it || it.key) { ui.toast('Um item de história. Não pode ser usado aqui.', '', '✦'); return; }
    if (!game.inventory[id]) return;
    let target = null;
    if (it.target === 'ally') {
      const options = game.party.map((m) => ({ label: `${m.name}  (${m.hp}/${m.maxHp} HP)`, value: m.id }));
      const pick = await ui.choice('Usar em quem?', options);
      if (pick == null) return;
      target = game.party.find((m) => m.id === pick);
    }
    if (it.heal) {
      if (target.hp >= target.maxHp) { ui.toast(`${target.name} já está com HP cheio.`, '', '♥'); return; }
      target.hp = Math.min(target.maxHp, target.hp + it.heal);
      ui.toast(`${target.name} recuperou ${it.heal} de HP.`, 'gold', '♥');
    }
    if (it.mp) {
      if (target.mp >= target.maxMp) { ui.toast(`${target.name} já está com MP cheio.`, '', '✦'); return; }
      target.mp = Math.min(target.maxMp, target.mp + it.mp);
      ui.toast(`${target.name} recuperou ${it.mp} de MP.`, 'gold', '✦');
    }
    if (it.cure) {
      if (!Object.keys(target.status || {}).length) { ui.toast(`${target.name} não precisa de antídoto.`, '', '✚'); return; }
      target.status = {};
      ui.toast(`${target.name} foi curado.`, 'gold', '✚');
    }
    if (it.full) {
      target.hp = target.maxHp; target.mp = target.maxMp; target.status = {};
      ui.toast(`${target.name} foi completamente restaurado.`, 'gold', '◈');
    }
    game.inventory[id]--;
    if (game.inventory[id] <= 0) delete game.inventory[id];
    audio.sfx('heal');
    ui.updateHUD(game);
    contentIndex = 0;
    renderContent();
  };

  const renderContent = () => {
    contentActions = [];
    const tab = tabs[tabIndex];
    navBtns.forEach((b, i) => b.classList.toggle('sel', i === tabIndex && focus === 'nav'));
    if (tab === 'status') {
      contentEl.innerHTML = statusHTML(game);
    } else if (tab === 'items') {
      contentEl.innerHTML = itemsHTML(game);
      const rows = [...contentEl.querySelectorAll('.item-row.clickable')];
      rows.forEach((row, i) => {
        row.classList.toggle('sel', focus === 'content' && i === contentIndex);
        row.addEventListener('mouseenter', () => { contentIndex = i; focus = 'content'; renderContent(); });
        row.addEventListener('click', () => { contentIndex = i; focus = 'content'; useItem(row.dataset.item); });
        contentActions.push({ type: 'item', id: row.dataset.item });
      });
      if (focus === 'content' && !rows.length) focus = 'nav';
    } else if (tab === 'journal') {
      contentEl.innerHTML = `<h3>Diário</h3>${journalHTML(game)}`;
    } else if (tab === 'save') {
      contentEl.innerHTML = `<h3>Salvar progresso</h3>
        <p style="font-size:18px;color:var(--muted);line-height:1.2">Grave sua jornada no capítulo atual. O progresso fica guardado neste navegador.</p>
        <div class="item-row clickable" id="save-row" style="margin-top:14px">
          <div class="item-ico">⚿</div>
          <div class="item-name">Salvar agora<small>${game.mapName || ''} · ${game.playTimeLabel || ''}</small></div>
          <div class="item-qty">${game.gold} ◈</div>
          <div class="item-use">Gravar</div>
        </div>`;
      const row = contentEl.querySelector('#save-row');
      row.classList.toggle('sel', focus === 'content');
      row.addEventListener('mouseenter', () => { focus = 'content'; renderContent(); });
      row.addEventListener('click', doSave);
      contentActions.push({ type: 'save' });
    } else if (tab === 'system') {
      contentEl.innerHTML = `<h3>Sistema</h3>
        <div class="item-list">
          <div class="item-row clickable" data-sys="mute"><div class="item-ico">♪</div><div class="item-name">Som<small>${audio.muted ? 'Desligado' : 'Ligado'}</small></div><div class="item-use">Alternar</div></div>
          <div class="item-row clickable" data-sys="controls"><div class="item-ico">⌨</div><div class="item-name">Controles<small>WASD/setas mover · Espaço interagir · Esc menu</small></div><div class="item-use">Ver</div></div>
          <div class="item-row clickable" data-sys="title"><div class="item-ico">✕</div><div class="item-name">Voltar ao título<small>O progresso não salvo será perdido.</small></div><div class="item-use">Sair</div></div>
        </div>`;
      const rows = [...contentEl.querySelectorAll('[data-sys]')];
      rows.forEach((row, i) => {
        row.classList.toggle('sel', focus === 'content' && i === contentIndex);
        row.addEventListener('mouseenter', () => { contentIndex = i; focus = 'content'; renderContent(); });
        row.addEventListener('click', () => sysAction(row.dataset.sys));
        contentActions.push({ type: 'sys', id: row.dataset.sys });
      });
      if (focus === 'content' && !rows.length) focus = 'nav';
    }
    renderNav();
  };

  const doSave = async () => {
    const ok = actions.save ? actions.save() : false;
    if (ok) { ui.toast('Progresso salvo.', 'gold', '⚿'); audio.sfx('save'); }
    else ui.toast('Não foi possível salvar agora.', 'red', '✕');
  };

  const sysAction = async (id) => {
    if (id === 'mute') { const m = audio.toggleMuted(); ui.updateMuteIcon(m); renderContent(); }
    if (id === 'controls') {
      await ui.modal({
        kicker: 'Controles', title: 'Como jogar',
        body: `<p style="font-size:19px;line-height:1.3">Mova com <b>WASD</b> ou setas. Interaja com <b>Espaço</b>, <b>Enter</b> ou <b>Z</b>. Abra o menu com <b>Esc</b> ou <b>X</b>.<br><br>Em batalhas, escolha ações com as setas e confirme com Enter. No celular, use o direcional e os botões A/B.</p>`,
        actions: [{ label: 'Entendi', value: 'ok', primary: true }],
      });
      renderContent();
    }
    if (id === 'title') {
      const v = await ui.modal({
        kicker: 'Sair', title: 'Voltar ao título?', sub: 'O progresso não salvo será perdido.',
        actions: [{ label: 'Cancelar', value: 'cancel', cancel: true }, { label: 'Voltar ao título', value: 'title', primary: true }],
      });
      if (v === 'title') finish('title');
    }
  };

  const finish = (result) => {
    Input.pop(handler);
    ui.closeScreen();
    audio.sfx('cancel');
    resolve(result);
  };

  let resolve;
  const done = new Promise((r) => { resolve = r; });

  const switchTab = (i) => {
    tabIndex = (i + tabs.length) % tabs.length;
    navIndex = tabIndex;
    contentIndex = 0;
    focus = 'nav';
    audio.sfx('cursor');
    renderContent();
  };

  const handler = (a) => {
    if (focus === 'nav') {
      if (a === 'up') { navIndex = (navIndex - 1 + tabs.length) % tabs.length; switchTab(navIndex); return true; }
      if (a === 'down') { navIndex = (navIndex + 1) % tabs.length; switchTab(navIndex); return true; }
      if (a === 'right' || a === 'confirm') {
        const tab = tabs[tabIndex];
        if (tab === 'save') { focus = 'content'; contentIndex = 0; renderContent(); return true; }
        if (tab === 'items' || tab === 'system') { focus = 'content'; contentIndex = 0; renderContent(); return true; }
        if (tab === 'status' || tab === 'journal') return true;
      }
      if (a === 'cancel') { finish('close'); return true; }
      return true;
    }
    // content focus
    if (a === 'up') { contentIndex = Math.max(0, contentIndex - 1); renderContent(); return true; }
    if (a === 'down') { contentIndex = Math.min(contentActions.length - 1, contentIndex + 1); renderContent(); return true; }
    if (a === 'cancel' || a === 'left') { focus = 'nav'; renderContent(); return true; }
    if (a === 'confirm') {
      const act = contentActions[contentIndex];
      if (!act) return true;
      if (act.type === 'item') useItem(act.id);
      if (act.type === 'save') doSave();
      if (act.type === 'sys') sysAction(act.id);
      return true;
    }
    return true;
  };

  navBtns.forEach((b, i) => {
    b.addEventListener('mouseenter', () => { navIndex = i; if (focus === 'nav') renderContent(); });
    b.addEventListener('click', () => { navIndex = i; switchTab(i); });
  });
  content.querySelector('.screen-close').addEventListener('click', () => finish('close'));
  Input.push(handler);
  renderContent();
  return done;
}

export async function shopMenu(game, stock, title = 'Mercador') {
  const content = document.createElement('div');
  content.className = 'screen';
  const render = () => {
    content.innerHTML = `
      <div class="screen-head">
        <div class="screen-title">${title}</div>
        <div style="display:flex;gap:14px;align-items:center">
          <span style="font-size:19px;color:var(--gold)">◈ ${game.gold}</span>
          <button class="screen-close">Sair</button>
        </div>
      </div>
      <div class="screen-body">
        <p style="font-size:17px;color:var(--muted);margin:0 0 12px">"Leve o que precisar. O amanhecer não espera ninguém."</p>
        <div class="item-list" id="shop-list">
          ${stock.map((id, i) => {
            const it = ITEMS[id];
            const own = game.inventory[id] || 0;
            const can = game.gold >= it.price;
            return `<div class="item-row clickable ${can ? '' : 'disabled'}" data-shop="${id}" data-i="${i}" style="${can ? '' : 'opacity:.42'}">
              <div class="item-ico">${it.icon || '◈'}</div>
              <div class="item-name">${it.name}<small>${it.desc}</small></div>
              <div class="item-qty">x${own}</div>
              <div class="item-use">◈ ${it.price}</div>
            </div>`;
          }).join('')}
        </div>
        <div style="margin-top:14px;font-size:15px;color:var(--muted)">↑↓ escolher · Enter comprar · Esc sair</div>
      </div>`;
    content.querySelector('.screen-close').addEventListener('click', () => finish());
    const rows = [...content.querySelectorAll('[data-shop]')];
    rows.forEach((row, i) => {
      row.classList.toggle('sel', i === sel);
      row.addEventListener('mouseenter', () => { sel = i; render(); });
      row.addEventListener('click', () => buy(row.dataset.shop));
    });
  };
  let sel = 0;
  let resolve;
  const done = new Promise((r) => { resolve = r; });
  const finish = () => { Input.pop(handler); ui.closeScreen(); audio.sfx('cancel'); resolve(); };
  const buy = (id) => {
    const it = ITEMS[id];
    if (game.gold < it.price) { ui.toast('Ouro insuficiente.', 'red', '◈'); audio.sfx('cancel'); return; }
    game.gold -= it.price;
    game.inventory[id] = (game.inventory[id] || 0) + 1;
    audio.sfx('chest');
    ui.toast(`Comprou ${it.name}.`, 'gold', it.icon || '◈');
    ui.updateHUD(game);
    render();
  };
  const handler = (a) => {
    if (a === 'up') { sel = Math.max(0, sel - 1); render(); return true; }
    if (a === 'down') { sel = Math.min(stock.length - 1, sel + 1); render(); return true; }
    if (a === 'confirm') { buy(stock[sel]); return true; }
    if (a === 'cancel') { finish(); return true; }
    return true;
  };
  ui.openScreen(content, { dim: true });
  Input.push(handler);
  render();
  return done;
}

// battle-ui.js — battle DOM menus, HUD and canvas rendering
import { Input, wait, clamp, rand, randInt, chance } from './util.js';
import { audio } from './audio.js';
import { ui } from './ui.js';
import { drawBattleBG, drawEnemy, drawCharacter, getPortrait, getEnemyThumb, FX } from './art.js';
import { SKILLS, ITEMS, STATUS_INFO, ELEMENTS } from './data.js';

const el = (sel) => document.querySelector(sel);
const elem = (tag, cls, html) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
};

export function setupBattleUI(state) {
  const root = el('#battle-ui');
  root.classList.remove('hidden');
  root.innerHTML = `
    <div class="battle-log" id="battle-log"></div>
    <div class="turn-order" id="turn-order"></div>
    <div class="boss-hud hidden" id="boss-hud">
      <div class="bh-top"><span id="boss-name"></span><span id="boss-hp"></span></div>
      <div class="bar boss"><i id="boss-fill"></i></div>
    </div>
    <div class="battle-party" id="battle-party"></div>
    <div class="battle-command" id="battle-command"></div>
    <div id="battle-target-layer"></div>`;
  state.ui = {
    root,
    log: el('#battle-log'),
    order: el('#turn-order'),
    party: el('#battle-party'),
    command: el('#battle-command'),
    target: el('#battle-target-layer'),
    boss: el('#boss-hud'),
    bossName: el('#boss-name'),
    bossHp: el('#boss-hp'),
    bossFill: el('#boss-fill'),
  };
  ui.showHUD(false);
  ui.setTouchVisible(false);
  ui.hideDialogue();
  state.log = [];
  state.logMsgs = [];
  syncHUD(state);
}

export function teardownBattleUI() {
  const root = el('#battle-ui');
  root.classList.add('hidden');
  root.innerHTML = '';
  ui.showHUD(true);
}

export function logMsg(state, text) {
  state.logMsgs.push(text);
  if (state.logMsgs.length > 3) state.logMsgs.shift();
  const box = state.ui.log;
  box.innerHTML = state.logMsgs.map((m, i) => `<p${i === state.logMsgs.length - 1 ? ' class="last"' : ''}>${m}</p>`).join('');
}

export function layoutBattle(state) {
  const w = window.innerWidth, h = window.innerHeight;
  const compact = w < 780;
  const n = state.enemies.length;
  const ex0 = compact ? w * 0.5 : w * 0.48;
  const ex1 = compact ? w * 0.9 : w * 0.88;
  const ey = compact ? h * 0.31 : h * 0.45;
  state.enemies.forEach((e, i) => {
    e.x = n === 1 ? (ex0 + ex1) * 0.5 : ex0 + (ex1 - ex0) * (i / (n - 1));
    e.y = ey + (n > 1 ? (i % 2) * h * 0.025 : 0) + (compact ? 0 : h * 0.02);
    e.scale = (e.scaleBase || 5) * (compact ? 0.72 : Math.min(1.15, Math.max(0.85, w / 1400)));
  });
  const alive = state.allies.filter((m) => m.hp > 0);
  const px0 = compact ? w * 0.13 : w * 0.2;
  const px1 = compact ? w * 0.43 : w * 0.43;
  const py = compact ? h * 0.52 : h * 0.67;
  alive.forEach((m, i) => {
    m.bx = alive.length === 1 ? (px0 + px1) / 2 : px0 + (px1 - px0) * (i / (alive.length - 1));
    m.by = py + (i % 2) * (compact ? 8 : 14);
    m.bs = compact ? 4.2 : 5.4;
  });
}

export function syncHUD(state) {
  if (!state.ui) return;
  layoutBattle(state);
  const party = state.ui.party;
  party.innerHTML = state.allies.map((m) => `
    <div class="battle-unit ${state.current === m ? 'active' : ''} ${m.hp <= 0 ? 'dead' : ''}" data-ally="${m.id}">
      <div class="bu-face"><canvas width="48" height="48" data-face="${m.id}"></canvas></div>
      <div>
        <div class="bu-name">${m.name}<span>Nv ${m.level}</span></div>
        <div class="bu-bars">
          <div class="bar hp ${m.hp / m.maxHp <= 0.25 ? 'low' : m.hp / m.maxHp <= 0.5 ? 'warn' : ''}"><i style="width:${clamp(m.hp / m.maxHp, 0, 1) * 100}%"></i></div>
          <div class="bar mp"><i style="width:${clamp(m.mp / m.maxMp, 0, 1) * 100}%"></i></div>
        </div>
        <div class="bu-status">${statusPips(m)}</div>
      </div>
    </div>`).join('');
  state.allies.forEach((m) => {
    const cv = party.querySelector(`[data-face="${m.id}"]`);
    if (cv) cv.getContext('2d').drawImage(getPortrait(m.sprite, 72), 0, 0, 48, 48);
  });
  // turn order
  const order = state.order || [];
  const start = state.turnIndex || 0;
  const upcoming = [];
  for (let i = 0; i < order.length && upcoming.length < 6; i++) {
    const a = order[(start + i) % order.length];
    if (a.hp > 0) upcoming.push(a);
  }
  state.ui.order.innerHTML = upcoming.map((a, i) => {
    const isEnemy = a.isEnemy;
    return `<div class="turn-chip ${isEnemy ? 'enemy' : ''} ${i === 0 ? 'now' : ''}" title="${a.name}">
      <canvas width="32" height="32" data-turn="${i}"></canvas><span>${(a.name || '?').split(' ')[0].slice(0, 5)}</span>
    </div>`;
  }).join('');
  upcoming.forEach((a, i) => {
    const cv = state.ui.order.querySelector(`[data-turn="${i}"]`);
    if (!cv) return;
    const g = cv.getContext('2d');
    if (a.isEnemy) g.drawImage(getEnemyThumb(a.id, 32), 0, 0);
    else g.drawImage(getPortrait(a.sprite, 72), 0, 0, 32, 32);
  });
  // boss bar
  const boss = state.enemies.find((e) => e.boss && e.hp > 0);
  if (boss) {
    state.ui.boss.classList.remove('hidden');
    state.ui.bossName.textContent = boss.name;
    state.ui.bossHp.textContent = `${Math.max(0, boss.hp)} / ${boss.maxHp}`;
    state.ui.bossFill.style.width = `${clamp(boss.hp / boss.maxHp, 0, 1) * 100}%`;
  } else {
    state.ui.boss.classList.add('hidden');
  }
}

export function statusPips(actor) {
  const pips = [];
  for (const [id, st] of Object.entries(actor.status || {})) {
    if (st.turns > 0) {
      const inf = STATUS_INFO[id];
      if (inf) pips.push(`<span class="status-pip" title="${inf.name}">${inf.icon}</span>`);
    }
  }
  for (const b of actor.buffs || []) {
    if (b.turns > 0) {
      const key = b.stat === 'atk' ? (b.mult >= 1 ? 'atkUp' : 'atkDown') : 'defUp';
      const inf = STATUS_INFO[key];
      pips.push(`<span class="status-pip" title="${inf.name}">${inf.icon}</span>`);
    }
  }
  return pips.join('');
}

// ---------------- Menus ----------------
function finishMenu(handler, resolve, value) {
  Input.pop(handler);
  resolve(value);
}

export function commandMenu(state, actor) {
  return new Promise((resolve) => {
    const root = state.ui.command;
    const items = [
      { label: 'Atacar', icon: '⚔', key: '1', value: 'attack', desc: 'Um golpe básico com a arma equipada.' },
      { label: 'Habilidade', icon: '✦', key: '2', value: 'skill', desc: 'Gaste MP para usar uma técnica especial.' },
      { label: 'Item', icon: '◈', key: '3', value: 'item', desc: 'Use um item da mochila.' },
      { label: 'Defender', icon: '◆', key: '4', value: 'defend', desc: 'Reduz o dano recebido até seu próximo turno.' },
      { label: 'Fugir', icon: '➜', key: '5', value: 'flee', desc: state.canFlee ? 'Tente escapar da batalha.' : 'Não é possível fugir desta batalha.', disabled: !state.canFlee },
    ];
    root.classList.add('with-party');
    root.innerHTML = `<div class="cmd-head"><span>${actor.name.toUpperCase()} · Nv ${actor.level}</span><span class="hint">Esc voltar</span></div>
      <div class="cmd-grid" id="cmd-grid"></div>
      <div class="cmd-desc" id="cmd-desc"></div>`;
    const grid = el('#cmd-grid');
    const desc = el('#cmd-desc');
    let sel = 0;
    const render = () => {
      grid.innerHTML = items.map((it, i) => `<button class="cmd-btn ${i === sel ? 'sel' : ''}" data-i="${i}" ${it.disabled ? 'disabled' : ''}>
        <span>${it.icon}</span><span>${it.label}</span><span class="key">${it.key}</span></button>`).join('');
      desc.innerHTML = `<b>${items[sel].label}</b> — ${items[sel].desc}`;
      grid.querySelectorAll('.cmd-btn').forEach((b, i) => {
        b.addEventListener('mouseenter', () => { if (!items[i].disabled) { sel = i; render(); audio.sfx('cursor'); } });
        b.addEventListener('click', () => { if (!items[i].disabled) choose(i); });
      });
    };
    const choose = (i) => {
      if (items[i].disabled) return;
      audio.sfx('confirm');
      root.classList.remove('with-party');
      root.innerHTML = '';
      finishMenu(handler, resolve, items[i].value);
    };
    const handler = (a) => {
      if (a === 'left') { sel = (sel + items.length - 1) % items.length; render(); return true; }
      if (a === 'right') { sel = (sel + 1) % items.length; render(); return true; }
      if (a === 'up') { sel = (sel + items.length - 2) % items.length; render(); return true; }
      if (a === 'down') { sel = (sel + 2) % items.length; render(); return true; }
      if (a === 'confirm') { choose(sel); return true; }
      if (a === 'cancel') { return true; }
      return true;
    };
    Input.push(handler);
    render();
  });
}

export function skillMenu(state, actor) {
  return new Promise((resolve) => {
    const root = state.ui.command;
    const skills = actor.skills.map((sid) => ({ sid, sk: SKILLS[sid] })).filter((s) => s.sk);
    root.innerHTML = `<div class="cmd-head"><span>HABILIDADES · ${actor.name.toUpperCase()}</span><span class="hint">MP ${actor.mp}/${actor.maxMp}</span></div>
      <div class="skill-list" id="skill-list"></div>
      <div class="cmd-desc" id="cmd-desc"></div>`;
    const list = el('#skill-list');
    const desc = el('#cmd-desc');
    let sel = 0;
    const render = () => {
      list.innerHTML = skills.map((s, i) => `<div class="skill-row ${i === sel ? 'sel' : ''} ${actor.mp < s.sk.cost ? 'disabled' : ''}" data-i="${i}">
        <span>${s.sk.name}</span><span class="cost">${s.sk.cost} MP</span></div>`).join('') +
        `<div class="skill-row ${sel === skills.length ? 'sel' : ''}" data-i="${skills.length}"><span>Voltar</span><span class="cost">—</span></div>`;
      const cur = skills[sel];
      desc.innerHTML = cur ? `<b>${cur.sk.name}</b> — ${cur.sk.desc}` : 'Retornar às ações.';
      list.querySelectorAll('.skill-row').forEach((row, i) => {
        row.addEventListener('mouseenter', () => { sel = i; render(); });
        row.addEventListener('click', () => choose(i));
      });
    };
    const choose = (i) => {
      if (i >= skills.length) { audio.sfx('cancel'); finishMenu(handler, resolve, null); return; }
      if (actor.mp < skills[i].sk.cost) { audio.sfx('cancel'); ui.toast('MP insuficiente.', 'red', '✦'); return; }
      audio.sfx('confirm');
      finishMenu(handler, resolve, skills[i].sid);
    };
    const handler = (a) => {
      if (a === 'up') { sel = (sel - 1 + skills.length + 1) % (skills.length + 1); render(); return true; }
      if (a === 'down') { sel = (sel + 1) % (skills.length + 1); render(); return true; }
      if (a === 'confirm') { choose(sel); return true; }
      if (a === 'cancel') { finishMenu(handler, resolve, null); return true; }
      return true;
    };
    Input.push(handler);
    render();
  });
}

export function itemMenu(state, game) {
  return new Promise((resolve) => {
    const root = state.ui.command;
    const ids = Object.keys(game.inventory).filter((id) => ITEMS[id] && !ITEMS[id].key && game.inventory[id] > 0);
    root.innerHTML = `<div class="cmd-head"><span>ITENS</span><span class="hint">Esc voltar</span></div>
      <div class="skill-list" id="item-list"></div><div class="cmd-desc" id="cmd-desc"></div>`;
    const list = el('#item-list');
    const desc = el('#cmd-desc');
    let sel = 0;
    const render = () => {
      list.innerHTML = ids.length ? ids.map((id, i) => `<div class="skill-row ${i === sel ? 'sel' : ''}" data-i="${i}">
        <span>${ITEMS[id].icon} ${ITEMS[id].name} <span style="color:var(--muted);font-size:14px">x${game.inventory[id]}</span></span><span class="cost">—</span></div>`).join('') +
        `<div class="skill-row ${sel === ids.length ? 'sel' : ''}" data-i="${ids.length}"><span>Voltar</span><span class="cost">—</span></div>`
        : `<div class="skill-row sel"><span>Mochila vazia</span></div><div class="skill-row" data-i="0"><span>Voltar</span></div>`;
      const cur = ids[sel];
      desc.innerHTML = cur ? ITEMS[cur].desc : 'Retornar às ações.';
      list.querySelectorAll('.skill-row').forEach((row, i) => {
        row.addEventListener('mouseenter', () => { sel = i; render(); });
        row.addEventListener('click', () => choose(i));
      });
    };
    const choose = (i) => {
      if (!ids.length || i >= ids.length) { audio.sfx('cancel'); finishMenu(handler, resolve, null); return; }
      audio.sfx('confirm');
      finishMenu(handler, resolve, ids[i]);
    };
    const handler = (a) => {
      if (a === 'up') { sel = (sel - 1 + ids.length + 1) % (ids.length + 1); render(); return true; }
      if (a === 'down') { sel = (sel + 1) % (ids.length + 1); render(); return true; }
      if (a === 'confirm') { choose(sel); return true; }
      if (a === 'cancel') { finishMenu(handler, resolve, null); return true; }
      return true;
    };
    Input.push(handler);
    render();
  });
}

export function targetMenu(state, opts = {}) {
  const side = opts.side || 'enemy';
  const list = (side === 'enemy' ? state.enemies : state.allies).filter((a) => opts.allowDead ? true : a.hp > 0);
  return new Promise((resolve) => {
    const layer = state.ui.target;
    if (!list.length) { resolve(null); return; }
    let sel = 0;
    const render = () => {
      layer.innerHTML = `<div class="target-layer">${list.map((a, i) => `
        <button class="target-card ${i === sel ? 'sel' : ''}" data-i="${i}">
          <div class="tc-name">${a.name}</div>
          <div class="tc-sub">${side === 'enemy' ? (a.hp > 0 ? 'Vivo' : 'Caído') : `${a.hp}/${a.maxHp} HP`}</div>
          ${side === 'enemy' ? `<div class="bar hp"><i style="width:${clamp(a.hp / a.maxHp, 0, 1) * 100}%"></i></div>` : ''}
        </button>`).join('')}</div>`;
      layer.querySelectorAll('.target-card').forEach((b, i) => {
        b.addEventListener('mouseenter', () => { sel = i; state.hoverTarget = list[i]; render(); });
        b.addEventListener('click', () => choose(i));
      });
      state.hoverTarget = list[sel];
    };
    const choose = (i) => {
      if (!list[i]) return;
      if (side === 'enemy' && list[i].hp <= 0) { audio.sfx('cancel'); return; }
      audio.sfx('confirm');
      state.hoverTarget = null;
      layer.innerHTML = '';
      finishMenu(handler, resolve, list[i]);
    };
    const handler = (a) => {
      if (a === 'left' || a === 'up') { sel = (sel - 1 + list.length) % list.length; render(); return true; }
      if (a === 'right' || a === 'down') { sel = (sel + 1) % list.length; render(); return true; }
      if (a === 'confirm') { choose(sel); return true; }
      if (a === 'cancel') { state.hoverTarget = null; layer.innerHTML = ''; finishMenu(handler, resolve, null); return true; }
      return true;
    };
    Input.push(handler);
    render();
  });
}

// ---------------- Rendering ----------------
export function drawBattleFrame(state, now) {
  const dt = state.lastTime ? Math.min(0.05, (now - state.lastTime) / 1000) : 0.016;
  state.lastTime = now;
  state.time += dt;
  const g = state.ctx;
  const w = state.w, h = state.h;
  if (!state.fx) state.fx = new FX();
  state.fx.update(dt);
  layoutBattle(state);

  // ambient particles
  state.ambientTimer = (state.ambientTimer || 0) + dt;
  const rate = state.ambient === 'snow' ? 0.05 : state.ambient === 'embers' ? 0.08 : 0.18;
  while (state.ambientTimer > rate) {
    state.ambientTimer -= rate;
    if (state.ambient === 'snow') {
      state.fx.particles.push({ x: rand(0, w), y: -10, vx: rand(-12, 12), vy: rand(30, 70), life: 0, max: rand(4, 8), size: rand(1, 3), color: '#e8f4ff', gravity: 4, glow: false, drag: 1 });
    } else if (state.ambient === 'embers') {
      state.fx.particles.push({ x: rand(0, w), y: h * 0.9, vx: rand(-10, 10), vy: rand(-50, -20), life: 0, max: rand(1.5, 3.5), size: rand(1, 3), color: chance(0.5) ? '#ff9a4a' : '#ffd27a', gravity: -6, glow: true, drag: 0.99 });
    } else {
      state.fx.particles.push({ x: rand(0, w), y: rand(0, h), vx: rand(-6, 6), vy: rand(-6, 6), life: 0, max: rand(2, 5), size: rand(1, 2), color: '#c8d0e0', gravity: 0, glow: false, drag: 1 });
    }
  }

  // update actor animations
  const all = [...state.enemies, ...state.allies];
  for (const a of all) {
    if (a.flashT > 0) a.flashT = Math.max(0, a.flashT - dt);
    if (a.anim) {
      a.anim.t += dt;
      if (a.anim.t >= a.anim.dur) a.anim = null;
    }
  }

  const shake = state.fx.offset();
  g.save();
  g.translate(shake.x, shake.y);
  drawBattleBG(g, w, h, state.bg, state.time);

  // party sprites
  const alive = state.allies.filter((m) => m.hp > 0);
  for (const m of alive) {
    let dx = 0, dy = 0;
    if (m.anim) {
      const p = Math.sin(clamp(m.anim.t / m.anim.dur, 0, 1) * Math.PI);
      dx = (m.anim.dx || 34) * p;
      dy = -6 * p;
    }
    const bob = Math.sin(state.time * 2 + (m.id.length)) * 1.2;
    drawCharacter(g, m.sprite, m.bx + dx, m.by + bob + dy, 'right', 0, m.bs, { flash: m.flashT > 0 });
    if (state.current === m && state.phase === 'command') {
      g.fillStyle = 'rgba(231,199,123,.85)';
      const ay = m.by - 28 * m.bs - 18 + Math.sin(state.time * 4) * 3;
      g.beginPath(); g.moveTo(m.bx, ay); g.lineTo(m.bx - 7, ay - 9); g.lineTo(m.bx + 7, ay - 9); g.closePath(); g.fill();
    }
  }
  // dead allies
  for (const m of state.allies.filter((x) => x.hp <= 0)) {
    g.save(); g.globalAlpha = 0.28; g.translate(0, 10);
    drawCharacter(g, m.sprite, m.bx, m.by, 'right', 0, m.bs, { alpha: 0.7 });
    g.restore();
  }

  // enemies
  for (const e of state.enemies) {
    if (e.hp <= 0 && !e.deadDrawn) continue;
    let dx = 0, dy = 0;
    if (e.anim) {
      const p = Math.sin(clamp(e.anim.t / e.anim.dur, 0, 1) * Math.PI);
      dx = (e.anim.dx || -34) * p;
    }
    if (e.hp <= 0) {
      g.save(); g.globalAlpha = Math.max(0, 0.35 - (e.deadT || 0) * 0.1);
      drawEnemy(g, e.id, e.x, e.y + 8, e.scale, state.time, { alpha: 0.35, bob: false });
      g.restore();
      e.deadT = (e.deadT || 0) + dt;
      continue;
    }
    drawEnemy(g, e.id, e.x + dx, e.y, e.scale, state.time, { flash: e.flashT > 0, phase: e.bobPhase });
    // HP bar
    const bw = clamp(e.scale * 26, 64, 170);
    const bx = e.x - bw / 2, by = e.y - (e.scale * 48) - 18;
    g.fillStyle = 'rgba(4,7,14,.8)';
    g.fillRect(bx - 2, by - 2, bw + 4, 14);
    g.fillStyle = '#3a1520'; g.fillRect(bx, by, bw, 6);
    const pct = clamp(e.hp / e.maxHp, 0, 1);
    const grd = g.createLinearGradient(bx, by, bx + bw, by);
    grd.addColorStop(0, '#8e2737'); grd.addColorStop(0.6, '#e35f72'); grd.addColorStop(1, '#ff9aa7');
    g.fillStyle = grd; g.fillRect(bx, by, bw * pct, 6);
    g.strokeStyle = 'rgba(231,199,123,.35)'; g.lineWidth = 1; g.strokeRect(bx + 0.5, by + 0.5, bw - 1, 5);
    g.font = '700 13px "VT323", monospace';
    g.textAlign = 'center'; g.textBaseline = 'bottom';
    g.fillStyle = 'rgba(8,8,14,.8)'; g.fillText(e.name, e.x + 1, by - 4);
    g.fillStyle = '#e8e0cc'; g.fillText(e.name, e.x, by - 5);
    // target marker
    if (state.hoverTarget === e) {
      g.fillStyle = '#ffe6a3';
      const ay = by - 20 + Math.sin(state.time * 6) * 3;
      g.beginPath(); g.moveTo(e.x, ay + 10); g.lineTo(e.x - 8, ay); g.lineTo(e.x + 8, ay); g.closePath(); g.fill();
    }
  }
  // ally target marker
  if (state.hoverTarget && !state.hoverTarget.isEnemy) {
    const m = state.hoverTarget;
    g.strokeStyle = 'rgba(255,230,163,.9)'; g.lineWidth = 3;
    g.beginPath(); g.ellipse(m.bx, m.by, 30, 8, 0, 0, Math.PI * 2); g.stroke();
  }

  state.fx.draw(g);
  g.restore();
}

export function battleActorPos(actor) {
  if (actor.isEnemy) return { x: actor.x, y: actor.y - actor.scale * 28, h: actor.scale * 48 };
  return { x: actor.bx, y: actor.by - actor.bs * 14, h: actor.bs * 28 };
}

export function elementColor(element) {
  return ELEMENTS[element]?.color || '#fff3cf';
