282: // ------------------------------------------------------------------ movement loop
283: function updateExplore(dt) {
284:   if (mode !== 'explore' || isBusy() || !player) return;
285:   if (player.bump > 0) player.bump = Math.max(0, player.bump - dt);
286:   if (player.moving) {
287:     player.t += dt / STEP_TIME;
288:     if (player.t >= 1) {
289:       player.t = 1;
290:       player.moving = false;
291:       player.fromX = player.x;
292:       player.fromY = player.y;
293:       onStepComplete();
294:     }
295:     return;
296:   }
297:   let dir = null;
298:   if (Input.isDown('up')) dir = 'up';
299:   else if (Input.isDown('down')) dir = 'down';
300:   else if (Input.isDown('left')) dir = 'left';
301:   else if (Input.isDown('right')) dir = 'right';
302:   if (dir) {
303:     player.dir = dir;
304:     tryMove(dir);
305:   }
306: }
