40: function drawHair(g, d, facing, topY = 3) {
41:   const h = d.hair, h2 = d.hair2 || h, o = '#1a1218';
42:   const style = d.hairStyle || 'short';
43:   if (style === 'bald') {
44:     px(g, d.skin2, 6, topY + 1, 8, 2);
45:     px(g, '#e8e8e8', 6, topY + 5, 2, 2);
46:     px(g, '#e8e8e8', 12, topY + 5, 2, 2);
47:     return;
48:   }
49:   if (style === 'helmet') {
50:     px(g, o, 5, topY - 1, 10, 7);
51:     px(g, d.trim, 6, topY, 8, 5);
52:     px(g, '#dfe6ee', 7, topY + 1, 5, 2);
53:     px(g, '#8a94a2', 6, topY + 4, 8, 2);
54:     if (d.plume) { px(g, d.plume, 9, topY - 5, 2, 5); px(g, d.plume, 8, topY - 7, 3, 3); }
55:     return;
56:   }
57:   if (style === 'hood') {
58:     px(g, o, 4, topY - 2, 12, 10);
59:     px(g, d.cape || d.top2, 5, topY - 1, 10, 7);
60:     px(g, d.hair2 || d.top2, 6, topY + 1, 8, 4);
61:     px(g, d.skin, 7, topY + 3, 6, 4);
62:     px(g, '#2a1e3a', 7, topY + 3, 6, 1);
63:     return;
64:   }
65:   if (style === 'bandana') {
66:     px(g, o, 5, topY - 1, 10, 5);
67:     px(g, d.trim, 5, topY - 1, 10, 3);
68:     px(g, '#2a1a12', 5, topY + 2, 10, 2);
69:     px(g, d.trim, 14, topY + 1, 3, 2);
70:     return;
71:   }
72:   if (style === 'long') {
73:     px(g, o, 4, topY - 1, 12, 9);
74:     px(g, h, 5, topY, 10, 5);
75:     px(g, h, 5, topY + 4, 3, 8);
76:     px(g, h, 12, topY + 4, 3, 8);
77:     px(g, h2, 13, topY + 5, 2, 6);
78:     px(g, h, 6, topY - 1, 7, 2);
79:     return;
80:   }
81:   if (style === 'ponytail') {
82:     px(g, o, 5, topY - 1, 10, 5);
83:     px(g, h, 6, topY, 9, 4);
84:     px(g, h, 5, topY + 2, 2, 4);
85:     px(g, h2, 15, topY + 1, 2, 6);
