91:     px(g, h, 5, topY - 1, 10, 4);
92:     px(g, h, 5, topY - 3, 2, 3);
93:     px(g, h, 9, topY - 4, 2, 4);
94:     px(g, h, 13, topY - 3, 2, 3);
95:     px(g, h2, 5, topY + 3, 10, 1);
96:     return;
97:   }
98:   // short
