144: function drawHuman(g, d, facing, frame) {
145:   const o = '#17121a';
146:   const walk = frame === 1 || frame === 2;
147:   const step = frame === 1 ? 1 : frame === 2 ? -1 : 0;
148:   const bob = walk ? 1 : 0;
149:   const top = 10 - bob;
150: 
151:   // ground shadow
152:   g.fillStyle = 'rgba(0,0,0,.3)';
153:   g.beginPath(); g.ellipse(10, 26, 5.5, 1.8, 0, 0, Math.PI * 2); g.fill();
154: 
155:   if (facing === 'up') {
156:     // cape
157:     if (d.cape) {
158:       px(g, o, 4, top - 1, 12, 12);
159:       px(g, d.cape2 || d.cape, 5, top, 10, 11);
160:       px(g, d.cape, 5, top, 10, 2);
161:       px(g, d.cape2 || d.cape, 6, top + 8, 8, 3);
162:     }
163:     // legs
164:     px(g, o, 5, 19 - bob, 4, 8);
165:     px(g, o, 11, 19 - bob, 4, 8);
166:     px(g, d.pants, 6, 20 - bob, 2, 5 + (step > 0 ? 1 : 0));
167:     px(g, d.pants, 12, 20 - bob, 2, 5 + (step < 0 ? 1 : 0));
168:     px(g, d.boots, 6, 25 - bob, 3, 2);
169:     px(g, d.boots, 12, 25 - bob, 3, 2);
170:     // body
171:     px(g, o, 4, top - 1, 12, 11);
172:     px(g, d.top, 5, top, 10, 10);
173:     px(g, d.top2, 5, top + 6, 10, 4);
174:     px(g, d.trim, 5, top + 7, 10, 1);
175:     px(g, d.top2, 5, top, 3, 7);
176:     // arms
177:     px(g, o, 2, top + 1, 3, 8);
178:     px(g, o, 15, top + 1, 3, 8);
179:     px(g, d.top2, 3, top + 2, 2, 6);
180:     px(g, d.top2, 15, top + 2, 2, 6);
181:     px(g, d.skin, 3, top + 8, 2, 2);
182:     px(g, d.skin, 15, top + 8, 2, 2);
183:     // head
184:     px(g, o, 5, 2, 10, 10);
185:     px(g, d.skin, 6, 3, 8, 8);
186:     px(g, d.skin2, 12, 4, 2, 6);
187:     drawHair(g, d, 'up', 3);
188:     drawWeapon(g, d, 'up');
189:     return;
190:   }
191: 
192:   if (facing === 'right') {
193:     if (d.cape) {
194:       px(g, o, 3, top - 1, 9, 13);
195:       px(g, d.cape2 || d.cape, 4, top, 7, 12);
196:       px(g, d.cape, 4, top, 5, 2);
197:     }
198:     // back arm
199:     px(g, o, 5, top + 2, 3, 7);
200:     px(g, d.top2, 5, top + 3, 2, 5);
201:     // legs
202:     const l1 = 20 - bob - (step > 0 ? 1 : 0), l2 = 20 - bob - (step < 0 ? 1 : 0);
203:     px(g, o, 6, l1, 4, 7);
204:     px(g, o, 10, l2, 4, 7);
205:     px(g, d.pants, 7, l1 + 1, 2, 4);
206:     px(g, d.pants, 11, l2 + 1, 2, 4);
207:     px(g, d.boots, 7, l1 + 5, 3, 2);
208:     px(g, d.boots, 11, l2 + 5, 3, 2);
209:     // body
210:     px(g, o, 5, top - 1, 10, 11);
211:     px(g, d.top, 6, top, 8, 10);
212:     px(g, d.top2, 6, top + 6, 8, 4);
213:     px(g, d.trim, 6, top + 7, 8, 1);
214:     if (d.skirt) { px(g, o, 4, top + 8, 12, 6); px(g, d.skirt, 5, top + 8, 10, 5); }
215:     // front arm
216:     px(g, o, 12, top + 2, 3, 8);
217:     px(g, d.top, 12, top + 2, 2, 5);
218:     px(g, d.skin, 12, top + 7, 2, 3);
219:     // head
220:     px(g, o, 6, 2, 9, 10);
221:     px(g, d.skin, 7, 3, 7, 8);
222:     px(g, d.skin2, 12, 4, 2, 6);
223:     px(g, d.skin, 15, 7, 1, 2); // nose
224:     // eye
225:     px(g, d.eye || '#241610', 12, 6, 1, 2);
226:     drawHair(g, d, 'right', 3);
227:     if (d.beard) { px(g, d.beard, 10, 10, 4, 2); px(g, d.beard, 12, 9, 2, 1); }
228:     drawWeapon(g, d, 'right');
229:     return;
230:   }
231: 
232:   // facing down
233:   if (d.cape) {
234:     px(g, o, 3, top - 1, 14, 14);
235:     px(g, d.cape2 || d.cape, 4, top, 12, 13);
236:     px(g, d.cape, 4, top, 12, 2);
237:     px(g, d.cape2 || d.cape, 4, top + 10, 12, 2);
238:   }
239:   // legs
240:   const l1 = 20 - bob - (step > 0 ? 1 : 0), l2 = 20 - bob - (step < 0 ? 1 : 0);
241:   px(g, o, 5, l1, 4, 7);
242:   px(g, o, 11, l2, 4, 7);
243:   px(g, d.pants, 6, l1 + 1, 2, 4);
244:   px(g, d.pants, 12, l2 + 1, 2, 4);
245:   px(g, d.boots, 6, l1 + 5, 3, 2);
246:   px(g, d.boots, 12, l2 + 5, 3, 2);
247:   // arms behind
248:   px(g, o, 2, top + 1, 3, 8);
249:   px(g, o, 15, top + 1, 3, 8);
250:   px(g, d.top2, 3, top + 2, 2, 5);
251:   px(g, d.top2, 15, top + 2, 2, 5);
252:   // body
253:   px(g, o, 4, top - 1, 12, 11);
254:   px(g, d.top, 5, top, 10, 10);
255:   px(g, d.top2, 11, top, 4, 10);
256:   px(g, d.top, 5, top, 3, 6);
257:   px(g, d.trim, 5, top + 7, 10, 1);
258:   px(g, '#2a2430', 8, top + 7, 4, 2);
259:   px(g, d.trim, 9, top + 7, 2, 2);
260:   if (d.skirt) { px(g, o, 4, top + 8, 12, 7); px(g, d.skirt, 5, top + 8, 10, 6); px(g, d.top2, 5, top + 12, 10, 2); }
261:   // hands
262:   px(g, d.skin, 3, top + 8, 2, 2);
263:   px(g, d.skin, 15, top + 8, 2, 2);
264:   // head
265:   px(g, o, 5, 2, 10, 10);
266:   px(g, d.skin, 6, 3, 8, 8);
267:   px(g, d.skin2, 12, 4, 2, 7);
268:   px(g, d.skin2, 6, 9, 8, 2);
269:   // eyes
270:   px(g, d.eye || '#241610', 8, 6, 1, 2);
271:   px(g, d.eye || '#241610', 12, 6, 1, 2);
272:   px(g, '#fff', 8, 6, 1, 1);
273:   px(g, '#fff', 12, 6, 1, 1);
274:   // mouth
275:   px(g, d.skin2, 10, 9, 2, 1);
276:   drawHair(g, d, 'down', 3);
277:   if (d.beard) {
278:     px(g, d.beard, 7, 9, 7, 3);
279:     px(g, d.beard, 9, 11, 3, 1);
280:     px(g, d.skin2, 10, 9, 2, 1);
281:   }
282:   drawWeapon(g, d, 'down');
283: }
