292: export function getCharSprite(id, facing = 'down', frame = 0) {
293:   const def = HUMANS[id];
294:   if (!def) return getCharSprite('villager1', facing, frame);
295:   const key = `${id}|${facing}|${frame}`;
296:   if (cache.has(key)) return cache.get(key);
297:   const { c, g } = makeCanvas(SPRITE_W, SPRITE_H);
298:   g.imageSmoothingEnabled = false;
299:   if (facing === 'left') {
300:     const { c: rc, g: rg } = makeCanvas(SPRITE_W, SPRITE_H);
301:     drawHuman(rg, def, 'right', frame);
302:     const flipped = flipCanvas(rc);
303:     g.drawImage(flipped, 0, 0);
304:   } else {
305:     drawHuman(g, def, facing, frame);
306:   }
307:   cache.set(key, c);
308:   return c;
309: }
