311: function getSilhouette(id, facing, frame) {
312:   const key = `${id}|${facing}|${frame}`;
313:   if (silhouetteCache.has(key)) return silhouetteCache.get(key);
314:   const src = getCharSprite(id, facing, frame);
315:   const { c, g } = makeCanvas(SPRITE_W, SPRITE_H);
316:   g.drawImage(src, 0, 0);
317:   g.globalCompositeOperation = 'source-atop';
318:   g.fillStyle = '#fff';
319:   g.fillRect(0, 0, SPRITE_W, SPRITE_H);
320:   silhouetteCache.set(key, c);
321:   return c;
322: }
