324: // Draw character with feet anchored at (x,y)
325: export function drawCharacter(g, id, x, y, facing = 'down', frame = 0, scale = 3, opts = {}) {
326:   const spr = opts.flash ? getSilhouette(id, facing, frame) : getCharSprite(id, facing, frame);
327:   const w = SPRITE_W * scale, h = SPRITE_H * scale;
328:   const dx = Math.round(x - w / 2), dy = Math.round(y - h);
329:   if (opts.alpha != null) g.globalAlpha = opts.alpha;
330:   g.drawImage(spr, dx, dy, w, h);
331:   if (opts.flash) {
332:     g.globalCompositeOperation = 'lighter';
333:     g.globalAlpha = (opts.alpha ?? 1) * 0.6;
334:     g.drawImage(spr, dx, dy, w, h);
335:     g.globalCompositeOperation = 'source-over';
336:   }
337:   g.globalAlpha = 1;
338: }
