63: export function layoutBattle(state) {
64:   const w = state.w || window.innerWidth;
65:   const h = state.h || window.innerHeight;
66:   const compact = w < 780;
67:   const portrait = h > w * 1.15;
68:   const n = state.enemies.length;
69:   // Enemy ground line sits farther back than the party, but never so high that
70:   // sprites collide with the battle log / turn order.
71:   const groundY = portrait ? h * 0.34 : compact ? h * 0.46 : h * 0.54;
72:   const topLimit = portrait ? 126 : compact ? 92 : 120;
73:   const x0 = portrait ? w * 0.34 : compact ? w * 0.52 : w * 0.50;
74:   const x1 = portrait ? w * 0.94 : w * 0.90;
75: 
76:   // 1) Choose a target height in screen terms (bosses slightly larger).
77:   // 2) Fit the whole group into the available width, shrinking if necessary.
78:   // 3) Anchor every enemy at a shared ground line so they feel grounded.
79:   const metrics = state.enemies.map((e) => enemySpriteMetrics(e.id));
80:   const gap = n > 1 ? Math.min(26, (x1 - x0) * 0.045) : 0;
81:   state.enemies.forEach((e, i) => {
82:     const boss = !!e.boss;
83:     const targetH = clamp(
84:       h * (boss ? (portrait ? 0.24 : 0.28) : (portrait ? 0.155 : 0.20)),
85:       compact ? 56 : 80,
86:       boss ? 250 : 185,
87:     );
88:     const maxH = groundY - topLimit;
89:     const height = Math.max(40, Math.min(targetH, maxH));
90:     e.scale = height / metrics[i].h;
91:   });
92:   let totalW = 0;
93:   state.enemies.forEach((e, i) => {
94:     e.drawW = metrics[i].w * e.scale;
95:     e.drawH = metrics[i].h * e.scale;
96:     totalW += e.drawW + (i ? gap : 0);
97:   });
98:   const availW = x1 - x0;
99:   if (totalW > availW && totalW > 0) {
100:     const shrink = availW / totalW;
101:     state.enemies.forEach((e, i) => {
102:       e.scale *= shrink;
103:       e.drawW *= shrink;
104:       e.drawH *= shrink;
105:     });
106:     totalW = availW;
107:   }
108:   let cursor = (x0 + x1) / 2 - totalW / 2;
109:   state.enemies.forEach((e, i) => {
110:     e.x = cursor + e.drawW / 2;
111:     cursor += e.drawW + gap;
112:     e.y = groundY + (n > 1 && !portrait ? (i % 2) * h * 0.012 : 0);
113:   });
114: 
115:   const alive = state.allies.filter((m) => m.hp > 0);
116:   const px0 = compact ? w * 0.13 : w * 0.2;
117:   const px1 = compact ? w * 0.43 : w * 0.43;
118:   const py = compact ? h * 0.52 : h * 0.67;
119:   alive.forEach((m, i) => {
120:     m.bx = alive.length === 1 ? (px0 + px1) / 2 : px0 + (px1 - px0) * (i / (alive.length - 1));
121:     m.by = py + (i % 2) * (compact ? 8 : 14);
122:     m.bs = compact ? 4.2 : 5.4;
123:   });
124: }
